ruleSearch.bookList:
.book-coverlist
<js>
result.toArray().slice(0, 3).map(el => {
	var url = String(el.select('a:eq(0)').attr('href')).replace(/^\//, baseUrl.match(/(.+?\/\/[^\/]+\/)/)[1]);
	var J = org.jsoup.Jsoup.parse(java.ajax(url));
	var o = selector => String(J.select(selector).text());
	var og = selector => String(J.select('[property="og:' + selector + '"]').attr('content'));
	return {
		name: og('novel:book_name').replace(/(全文|小说|免费阅读|最新章节).*|[(（].*[）)]/g, ''),
		author: og('novel:author'),
		kind: og('novel:category') + ',' + og('novel:status').replace(/中|已/, ''),
		latest: og('novel:latest_chapter_name').replace(/^(正文|VIP章节|最新章节)?(\s+|_)|[\(（【].*[求更谢乐发推].*/g, '') + ' • ' + og('novel:update_time').replace(/(T|\s).*/, ' ').replace(/\//g, '-'),
		intro: og('description').replace(/.*(观看小说|简介)[:：]|各位书友.*/g, '').replace(/\s+/g, ''),
		cover: og('image'),
		url: url,
	};
}); 
</js>

ruleContent.nextContentUrl:
@js:
try{
page=result.match(/\(\d*\/(\d*)\)/)[1];
//java.log(page)
list=[];
if(page>=2){
for(var i=2;i<=page;i++){
href=baseUrl.replace(/(_\d*)?.html/,"_"+i+".html");
list.push(href);
}
}
list
}catch(e){java.getString('@@.section-opt a@href')}

ruleToc.chapterList:
.panel-chapterlist.0@dd@a
@js:
var r = result, n = 0;
Array.from(r, (x, i) => {
	var name = x.text(),
	link = x.attr("href");
	dir = {text: name, href: link,
	toString: function(){
		return JSON.stringify(this)}
	};
	if(/javascript/i.test(x) && (a = r[i + 1]) ){
		msg = "目录缺失，尝试修复中，稍等！";
		n += 1; n < 2 && java.log(msg);
		 //java.toast(msg)
			var ah = a.attr("href"), 
			url = /^https?/.test(ah) ? 
			ah : book.origin + ah;
			var h = java.ajax(url);
			path = "text.上一@href";
		u = java.getString(path, h);
		dir.href = u;
		//java.log(dir.toString())
		}
	return dir
	});

